#include "stm32g4xx.h"

void USART1_Init(void)
{
    /* 1. Enable peripheral clocks for GPIOA and USART1 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_USART1EN;

    /* 2. Configure PA9 (TX) and PA10 (RX) for Alternate Function 7 (USART1) */
    /* Set Alternate Function mode (10b) for PA9 and PA10 */
    GPIOA->MODER = (GPIOA->MODER & ~(GPIO_MODER_MODE9_Msk | GPIO_MODER_MODE10_Msk))
                 | (2U << GPIO_MODER_MODE9_Pos)
                 | (2U << GPIO_MODER_MODE10_Pos);

    /* Set high speed for PA9 (TX) */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED9_Pos);

    /* Set AF7 in AFR[1] (AFRH) for PA9 and PA10 */
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(GPIO_AFRH_AFSEL9_Msk | GPIO_AFRH_AFSEL10_Msk))
                  | (7U << GPIO_AFRH_AFSEL9_Pos)
                  | (7U << GPIO_AFRH_AFSEL10_Pos);

    /* 3. Configure USART1:
     *    Clock source is PCLK2 (170 MHz by reset default in RCC_CCIPR).
     *    Oversampling by 16: OVER8 = 0 (reset value).
     *    BRR = 170 MHz / 115200 = 1475.69 -> 1476.
     */
    USART1->BRR = 1476U;

    /* 4. Set 8 data bits, no parity (M0=0, M1=0, PCE=0 by reset default),
     *    1 stop bit (STOP=00b by reset default),
     *    enable Transmitter (TE) and Receiver (RE),
     *    and finally enable USART1 (UE).
     */
    USART1->CR1 = USART_CR1_TE | USART_CR1_RE;
    USART1->CR1 |= USART_CR1_UE;
}

