#include "stm32g4xx.h"

void Reconfigure_180MHz(void)
{
    /* 1. Temporarily switch SYSCLK to HSE (8 MHz) so PLL can be disabled */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_HSE;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_HSE)
    {
        /* Wait for switch to HSE */
    }

    /* 2. Disable the PLL */
    RCC->CR &= ~RCC_CR_PLLON;
    while ((RCC->CR & RCC_CR_PLLRDY) != 0)
    {
        /* Wait for PLL to stop */
    }

    /* 3. Increase Flash latency to 5 wait states for 180 MHz operation */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_5WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_5WS)
    {
        /* Wait for Flash latency update */
    }

    /* 4. Configure PLL for 180 MHz:
     *    Source: HSE = 8 MHz
     *    PLLM = 2  (8 MHz / 2 = 4 MHz input to VCO)
     *    PLLN = 90 (4 MHz * 90 = 360 MHz VCO)
     *    PLLR = 2  (360 MHz / 2 = 180 MHz SYSCLK)
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE
                 | (1U << RCC_PLLCFGR_PLLM_Pos)      /* PLLM = 2 */
                 | (90U << RCC_PLLCFGR_PLLN_Pos)     /* PLLN = 90 */
                 | (0U << RCC_PLLCFGR_PLLR_Pos)      /* PLLR = 2 */
                 | RCC_PLLCFGR_PLLREN;

    /* 5. Re-enable PLL and wait for lock */
    RCC->CR |= RCC_CR_PLLON;
    while ((RCC->CR & RCC_CR_PLLRDY) == 0)
    {
        /* Wait for PLL lock */
    }

    /* 6. Switch SYSCLK back to PLL */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL)
    {
        /* Wait for SYSCLK switch */
    }

    /* 7. Update USART1 BRR for 180 MHz:
     *    BRR = 180,000,000 / 115200 = 1562.5 -> 1563 (+0.03% error)
     */
    USART1->CR1 &= ~USART_CR1_UE;
    USART1->BRR = 1563U;
    USART1->CR1 |= USART_CR1_UE;

    /* 8. Update I2C2 TIMINGR for 100 kHz from 180 MHz:
     *    t_I2CCLK = 5.555 ns
     *    PRESC  = 17 -> t_PRESC = (17 + 1) * 5.555 ns = 100 ns
     *    SCLL   = 52 -> t_LOW   = (52 + 1) * 100 ns  = 5.3 us
     *    SCLH   = 46 -> t_HIGH  = (46 + 1) * 100 ns  = 4.7 us
     *    Total Period   = (53 + 47) * 100 ns = 10.0 us -> exactly 100.0 kHz
     */
    I2C2->CR1 &= ~I2C_CR1_PE;
    I2C2->TIMINGR = (17U << I2C_TIMINGR_PRESC_Pos)
                  | (4U  << I2C_TIMINGR_SCLDEL_Pos)
                  | (2U  << I2C_TIMINGR_SDADEL_Pos)
                  | (46U << I2C_TIMINGR_SCLH_Pos)
                  | (52U << I2C_TIMINGR_SCLL_Pos);
    I2C2->CR1 |= I2C_CR1_PE;

    /* 9. Update TIM3 Prescaler for 1 kHz PWM from 180 MHz:
     *    PSC = 179 -> counter clock = 180 MHz / 180 = 1 MHz
     *    ARR remains 999 (1 kHz) and CCR1 remains 500 (50 % duty)
     */
    TIM3->PSC = 179U;
    TIM3->EGR |= TIM_EGR_UG; /* Force update generation to load new PSC shadow */
}
