    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM8EN;

    /* 2. Configure PC7 as alternate function AF4 (TIM8_CH2) */
    /* Set alternate function AF4 on PC7: AFRL7 = 4 */
    GPIOC->AFR[0] = (GPIOC->AFR[0] & ~GPIO_AFRL_AFSEL7_Msk) | (4U << GPIO_AFRL_AFSEL7_Pos);
    /* Set PC7 mode to Alternate Function (MODER7 = 0b10) */
    GPIOC->MODER = (GPIOC->MODER & ~GPIO_MODER_MODE7_Msk) | (2U << GPIO_MODER_MODE7_Pos);

    /* 3. Configure TIM8 time-base for 8 kHz PWM */
    /* TIM8CLK = 170 MHz.
     * f_PWM = TIM8CLK / ((PSC + 1) * (ARR + 1))
     * With PSC = 0: ARR + 1 = 170 MHz / 8 kHz = 21250 -> ARR = 21249.
     * For 30 % duty cycle: CCR2 = 21250 * 0.30 = 6375.
     */
    TIM8->PSC = 0U;
    TIM8->ARR = 21249U;
    TIM8->CCR2 = 6375U;

    /* 4. Configure Channel 2: PWM mode 1 (OC2M = 0110b), enable preload (OC2PE) */
    TIM8->CCMR1 = (TIM8->CCMR1 & ~(TIM_CCMR1_OC2M_Msk | TIM_CCMR1_CC2S_Msk))
                | (6U << TIM_CCMR1_OC2M_Pos)
                | TIM_CCMR1_OC2PE;

    /* 5. Enable Channel 2 output, active-high polarity (CC2P = 0) */
    TIM8->CCER &= ~TIM_CCER_CC2P;
    TIM8->CCER |= TIM_CCER_CC2E;

    /* 6. Enable Main Output (MOE) - required for advanced timer TIM8 */
    TIM8->BDTR |= TIM_BDTR_MOE;

    /* 7. Generate update event to transfer preloaded values into active registers */
    TIM8->EGR = TIM_EGR_UG;

    /* 8. Start counter */
    TIM8->CR1 |= TIM_CR1_CEN;

    while (1)
    {
    }
}
```

