#include "stm32g4xx.h"

int main(void) {
    /* 1. Enable peripheral clocks for GPIOA and TIM1 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PA8 and PA9 as Alternate Function AF6 (TIM1_CH1 and TIM1_CH2) */
    /* Set MODER8 and MODER9 to 0b10 (Alternate Function mode) */
    GPIOA->MODER &= ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos) | (2U << GPIO_MODER_MODE9_Pos);

    /* AFR[1] (AFRH) controls pins 8 to 15. Set AF6 (0b0110) for pins 8 and 9 */
    GPIOA->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL8_Pos) | (0xFU << GPIO_AFRH_AFSEL9_Pos));
    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos) | (6U << GPIO_AFRH_AFSEL9_Pos);

    /* 3. Configure TIM1 time base for 20 kHz */
    /* With SYSCLK = HCLK = PCLK2 = 170 MHz and APB2 prescaler = 1:
     * TIM1 kernel clock = 170 MHz.
     * Target frequency = 20 kHz.
     * Total counter period = 170,000,000 / 20,000 = 8500 cycles.
     * Setting PSC = 0 gives ARR = 8500 - 1 = 8499.
     */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;

    /* 4. Configure Duty Cycles:
     * Channel 1: 25% of 8500 = 2125 -> CCR1 = 2125
     * Channel 2: 75% of 8500 = 6375 -> CCR2 = 6375
     */
    TIM1->CCR1 = 2125;
    TIM1->CCR2 = 6375;

    /* 5. Configure Channels 1 and 2 in PWM Mode 1 with preload enabled */
    /* OC1M = 0110 (PWM Mode 1), OC1PE = 1; OC2M = 0110 (PWM Mode 1), OC2PE = 1 */
    TIM1->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk |
                     TIM_CCMR1_OC2M_Msk | TIM_CCMR1_CC2S_Msk);
    TIM1->CCMR1 |= (TIM_CCMR1_OC1M_1 | TIM_CCMR1_OC1M_2 | TIM_CCMR1_OC1PE) |
                   (TIM_CCMR1_OC2M_1 | TIM_CCMR1_OC2M_2 | TIM_CCMR1_OC2PE);

    /* 6. Enable channel outputs in CCER (CC1E = 1, CC2E = 1; CC1P = 0, CC2P = 0 for active-high) */
    TIM1->CCER |= TIM_CCER_CC1E | TIM_CCER_CC2E;

