The following C program configures the STM32G474 clock tree starting from reset (where HSI16 is 16 MHz, SYSCLK = 16 MHz, and all prescalers are 1).

```c
#include "stm32g4xx.h"

int main(void) {
    /* 1. Ensure HSI16 oscillator is ready */
    while ((RCC->CR & RCC_CR_HSIRDY) == 0) {
        /* Busy-wait until HSI16 stabilizes */
    }

    /* 2. Configure Flash memory access latency
     * For HCLK = 80 MHz in VCORE Range 1 normal mode, 2 wait states (LATENCY = 2)
     * are required (≤ 90 MHz requires 2 WS) [STM32G474_RM0440 p.98].
     * Increasing CPU frequency requires setting LATENCY before raising frequency [STM32G474_RM0440 p.152].
     */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_2WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_2WS) {
        /* Busy-wait until flash latency configuration is active */
    }

    /* 3. Configure bus prescalers in RCC_CFGR:
     * - AHB prescaler HPRE = 1 (not divided -> HCLK = SYSCLK = 80 MHz)
     * - APB1 prescaler PPRE1 = /2 (PCLK1 = HCLK / 2 = 40 MHz)
     * - APB2 prescaler PPRE2 = 1 (not divided -> PCLK2 = HCLK = 80 MHz)
     */
    RCC->CFGR = (RCC->CFGR & ~(RCC_CFGR_HPRE | RCC_CFGR_PPRE1 | RCC_CFGR_PPRE2))
              | RCC_CFGR_PPRE1_DIV2;

    /* 4. Configure PLL in RCC_PLLCFGR:
     * - PLLSRC = HSI16 (value 10b, RCC_PLLCFGR_PLLSRC_HSI) [STM32G474_RM0440 p.293]
     * - PLLM = 4: division factor = PLLM + 1 -> write 3 into PLLM[3:0]
     *   f_PLL_IN = 16 MHz / 4 = 4.0 MHz (allowed: 2.66 to 16 MHz) [STM32G474_Datasheet p.123]
     * - PLLN = 40: multiplication factor = 40 -> write 40 into PLLN[6:0]
     *   f_VCO = 4.0 MHz * 40 = 160 MHz (allowed: 96 to 344 MHz) [STM32G474_Datasheet p.123]
     * - PLLR = 2: division factor = 2 -> write 00b into PLLR[1:0] [STM32G474_RM0440 p.291]
     *   f_PLL_R = 160 MHz / 2 = 80 MHz (SYSCLK target, exact: 0.0 % error)
     * - PLLREN = 1: enable PLL 'R' output clock [STM32G474_RM0440 p.292]
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSI
                 | (3U << RCC_PLLCFGR_PLLM_Pos)
                 | (40U << RCC_PLLCFGR_PLLN_Pos)
                 | RCC_PLLCFGR_PLLREN;

    /* 5. Enable the Main PLL and wait for PLLRDY */
    RCC->CR |= RCC_CR_PLLON;
    while ((RCC->CR & RCC_CR_PLLRDY) == 0) {
