    /* ------------------------------------------------------------------
     * I2C1 Peripheral Configuration:
     * - Bus: APB1 (fCK = 170 MHz)
     * - Fast-mode (400 kHz controller)
     * - TIMINGR: PRESC=3, SCLDEL=9, SDADEL=9, SCLH=42, SCLL=55 (0x30992A37)
     *   -> tLOW = 1329.4 ns (>= 1.3 us), tHIGH = 1023.5 ns (>= 0.6 us)
     * - TIMINGR written while PE = 0, then enabled
     * ------------------------------------------------------------------ */
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C1EN;

    I2C1->CR1 &= ~I2C_CR1_PE;
    I2C1->TIMINGR = (3U << I2C_TIMINGR_PRESC_Pos)  |
