    GPIOC->OTYPER |= GPIO_OTYPER_OT4;
    GPIOA->OTYPER |= GPIO_OTYPER_OT8;

    /* Set high I/O speed */
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED4_Pos);
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);

    /* Enable internal pull-up resistors */
    GPIOC->PUPDR &= ~GPIO_PUPDR_PUPD4_Msk;
    GPIOC->PUPDR |= (1U << GPIO_PUPDR_PUPD4_Pos);
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD8_Msk;
    GPIOA->PUPDR |= (1U << GPIO_PUPDR_PUPD8_Pos);

    /* Set alternate function mode (0b10) */
    GPIOC->MODER &= ~GPIO_MODER_MODE4_Msk;
    GPIOC->MODER |= (2U << GPIO_MODER_MODE4_Pos);
    GPIOA->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos);

    /* Map PC4 to AF4 (I2C2_SCL) and PA8 to AF4 (I2C2_SDA) */
    GPIOC->AFR[0] &= ~(0xFU << GPIO_AFRL_AFSEL4_Pos);
    GPIOC->AFR[0] |= (4U << GPIO_AFRL_AFSEL4_Pos);
    GPIOA->AFR[1] &= ~(0xFU << GPIO_AFRH_AFSEL8_Pos);
    GPIOA->AFR[1] |= (4U << GPIO_AFRH_AFSEL8_Pos);

    /* 4. Configure USART1: 115200 baud, 8N1, oversampling by 16 */
    /* USARTDIV = 170,000,000 / 115,200 = 1475.69 -> 1476 (0x5C4, -0.02% error) */
    USART1->BRR = 1476U;
    /* Enable transmitter, receiver, and USART1 peripheral */
    USART1->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    /* 5. Configure I2C2: Fast Mode (400 kHz) at 170 MHz kernel clock */
    /* Ensure peripheral is disabled before programming TIMINGR */
    I2C2->CR1 &= ~I2C_CR1_PE;

    /* Timing parameters calculated for tLOW >= 1.3 us and tHIGH >= 0.6 us:
     * PRESC = 3  -> tPRESC = (3 + 1) * (1 / 170 MHz) = 23.53 ns
     * SCLDEL = 7 -> tSCLDEL = (7 + 1) * 23.53 ns = 188.2 ns (>= 100 ns)
     * SDADEL = 0 -> tSDADEL = 0 ns
     * SCLH = 37  -> tSCLH = (37 + 1) * 23.53 ns = 894.1 ns (>= 600 ns)
     * SCLL = 60  -> tSCLL = (60 + 1) * 23.53 ns = 1435.3 ns (>= 1300 ns)
