### Complete Bare-Metal Initialization Program (USART1 and I2C2)

```c
#include "stm32g4xx.h"

int main(void)
{
    /* 1. Enable peripheral bus clocks */
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C2EN;
    RCC->APB2ENR  |= RCC_APB2ENR_USART1EN;

    /* 2. Configure USART1 GPIO pins:
     *    - PA9:  USART1_TX (Alternate Function 7, Push-Pull, High Speed)
     *    - PA10: USART1_RX (Alternate Function 7, Input/Floating)
     */
    GPIOA->MODER &= ~(GPIO_MODER_MODE9_Msk | GPIO_MODER_MODE10_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE9_Pos) | (2U << GPIO_MODER_MODE10_Pos);
    GPIOA->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL9_Pos) | (0xFU << GPIO_AFRH_AFSEL10_Pos));
    GPIOA->AFR[1] |= ((7U << GPIO_AFRH_AFSEL9_Pos) | (7U << GPIO_AFRH_AFSEL10_Pos));

    /* 3. Configure I2C2 GPIO pins:
     *    - PA8: I2C2_SDA (AF4, Open-Drain, Pull-Up, Very High Speed)
     *    - PC4: I2C2_SCL (AF4, Open-Drain, Pull-Up, Very High Speed)
     *    Note: SCL is routed to PC4 because PA9 is dedicated to USART1_TX.
     */
    /* PA8 -> I2C2_SDA */
    GPIOA->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos);
    GPIOA->OTYPER |= GPIO_OTYPER_OT8;
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD8_Msk;
    GPIOA->PUPDR |= (1U << GPIO_PUPDR_PUPD8_Pos);
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);
    GPIOA->AFR[1] &= ~(0xFU << GPIO_AFRH_AFSEL8_Pos);
    GPIOA->AFR[1] |= (4U << GPIO_AFRH_AFSEL8_Pos);

    /* PC4 -> I2C2_SCL */
    GPIOC->MODER &= ~GPIO_MODER_MODE4_Msk;
    GPIOC->MODER |= (2U << GPIO_MODER_MODE4_Pos);
    GPIOC->OTYPER |= GPIO_OTYPER_OT4;
    GPIOC->PUPDR &= ~GPIO_PUPDR_PUPD4_Msk;
    GPIOC->PUPDR |= (1U << GPIO_PUPDR_PUPD4_Pos);
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED4_Pos);
    GPIOC->AFR[0] &= ~(0xFU << GPIO_AFRL_AFSEL4_Pos);
    GPIOC->AFR[0] |= (4U << GPIO_AFRL_AFSEL4_Pos);

    /* 4. Configure USART1:
     *    - Clock: PCLK2 = 170 MHz, OVER8 = 0 (oversampling by 16)
     *    - BRR = 170,000,000 / 115,200 = 1475.694 -> 1476 (0x05C4)
     *      Achieved baud rate = 115,176.15 baud (-0.02% error)
     *    - Frame format: 8 data bits, 1 stop bit, no parity (M0=0, M1=0, PCE=0, STOP=00)
     *    - Program BRR and CR2 before enabling USART (UE=1, TE=1, RE=1)
     */
    USART1->BRR = 1476U;
    USART1->CR2 &= ~USART_CR2_STOP_Msk;
    USART1->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    /* 5. Configure I2C2:
     *    - Disable peripheral (PE=0) before programming TIMINGR
     *    - Kernel clock: PCLK1 = 170 MHz (t_I2CCLK = 5.882 ns)
     *    - Fast-mode (400 kHz) Table 358 compliant settings:
     *        PRESC  = 15 -> tPRESC = 16 * 5.882 ns = 94.12 ns
     *        SCLDEL = 3  -> tSCLDEL = 4 * 94.12 ns = 376.5 ns
     *        SDADEL = 2  -> tSDADEL = 2 * 94.12 ns = 188.2 ns
     *        SCLH   = 8  -> tSCLH = 9 * 94.12 ns = 847.1 ns (>= 0.6 us)
     *        SCLL   = 14 -> tSCLL = 15 * 94.12 ns = 1411.8 ns (>= 1.3 us)
     *        TIMINGR = 0xF032080E
     *    - Enable peripheral (PE=1)
     */
    I2C2->CR1 &= ~I2C_CR1_PE;
    I2C2->TIMINGR = (15U << I2C_TIMINGR_PRESC_Pos)  |
                    (3U  << I2C_TIMINGR_SCLDEL_Pos) |
                    (2U  << I2C_TIMINGR_SDADEL_Pos) |
                    (8U  << I2C_TIMINGR_SCLH_Pos)   |
                    (14U << I2C_TIMINGR_SCLL_Pos);
    I2C2->CR1 |= I2C_CR1_PE;

    /* 6. Main loop */
    while (1)
    {
    }

    return 0;
}
