     * 7. TIM1 Configuration: 20 kHz, 25% Duty Cycle PWM on PA8
     *    Counter clock = 170 MHz
     *    PSC = 0
     *    ARR = 8499  => f = 170 MHz / 8500 = 20 kHz
     *    CCR1 = 2125 => Duty = 2125 / 8500 = 25%
     * --------------------------------------------------------- */
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;
    (void)RCC->APB2ENR;

    TIM1->PSC = 0;
    TIM1->ARR = 8499;
    TIM1->CCR1 = 2125;

