#include "stm32g4xx.h"

int main(void)
{
    /* =========================================================================
     * 1. CLOCK CONFIGURATION: 170 MHz (Range 1 Boost Mode, PLL from 8 MHz HSE)
     * ========================================================================= */
    /* Enable Power Controller clock and configure Range 1 Boost Mode (R1MODE = 0) */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* Flash latency: 4 WS (5 CPU cycles) required for 170 MHz in Range 1 Boost */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY_Msk) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY_Msk) != FLASH_ACR_LATENCY_4WS) {
        /* Wait for Flash latency to be applied */
    }

    /* Enable HSE crystal oscillator (8 MHz) and wait for stability */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY)) {
        /* Busy-wait on HSERDY */
    }

    /* Configure Main PLL:
     * Source = HSE (8 MHz)
     * M = 2   -> f_IN = 8 MHz / 2 = 4 MHz (allowed: 2.66 - 16 MHz)
     * N = 85  -> f_VCO = 4 MHz * 85 = 340 MHz (allowed: 96 - 344 MHz)
     * R = 2   -> f_PLL_R = 340 MHz / 2 = 170 MHz
     * Enable PLL 'R' output (PLLREN)
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE |
                   (1UL << RCC_PLLCFGR_PLLM_Pos) |
                   (85UL << RCC_PLLCFGR_PLLN_Pos) |
                   (0UL << RCC_PLLCFGR_PLLR_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* Enable PLL and wait for lock */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
        /* Busy-wait on PLLRDY */
    }

    /* Intermediate switch with AHB /2 to prevent clock glitch during switch */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE_Msk) | RCC_CFGR_HPRE_DIV2;
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW_Msk) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS_Msk) != RCC_CFGR_SWS_PLL) {
        /* Busy-wait until PLL is system clock source */
    }

    /* Set AHB prescaler to /1 -> HCLK = 170 MHz */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE_Msk) | RCC_CFGR_HPRE_DIV1;

    /* Ensure APB1 and APB2 prescalers are /1 -> PCLK1 = PCLK2 = 170 MHz */
    RCC->CFGR &= ~(RCC_CFGR_PPRE1_Msk | RCC_CFGR_PPRE2_Msk);

    /* =========================================================================
     * 2. GPIO CLOCKS
     * ========================================================================= */
    RCC->AHB2ENR |= (RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOBEN);

